# ─── Data loading ─────────────────────────────────────────────────────────────
def load_xenium_data(data_dir: str) -> dict:
    data_dir = os.path.abspath(data_dir)  # normalise so cache hashes are stable
    print(f"Loading from: {data_dir}", flush=True)
    zarr_path = os.path.join(data_dir, "spatialdata_xenium.zarr")
    if not os.path.isdir(zarr_path):
        print("  Generating spatialdata_xenium.zarr (one-time, ~30–60 s)…", flush=True)
        _build_xenium_sdata(data_dir)
    return _load_from_xenium_sdata(zarr_path, data_dir)


def _build_boundary_dict(df: pd.DataFrame) -> dict:
    """Return {cell_id: (vertex_x_array, vertex_y_array)} for fast polygon lookup.

    A cell with several rings (XOA 2+ nucleus boundaries: one `label_id` per nucleus)
    gets one NaN-separated vertex array, so the rings are not joined into one path."""
    if df.empty:
        return {}
    # Pre-sort by cell_id for contiguous slicing via numpy split
    cell_ids = df["cell_id"].values
    vx = df["vertex_x"].values
    vy = df["vertex_y"].values
    order = np.argsort(cell_ids, kind="mergesort")
    if "label_id" in df.columns:
        # stable two-pass sort → (cell_id, label_id), vertex order within a ring kept
        _lab = df["label_id"].values
        order = np.argsort(_lab, kind="mergesort")
        order = order[np.argsort(cell_ids[order], kind="mergesort")]
    cell_ids_s = cell_ids[order]
    vx_s = vx[order]
    vy_s = vy[order]
    if "label_id" in df.columns:
        _lab_s = _lab[order]
        _brk = np.flatnonzero((cell_ids_s[1:] == cell_ids_s[:-1]) & (_lab_s[1:] != _lab_s[:-1])) + 1
        if len(_brk):
            # NaN vertex between two rings of the same cell
            vx_s = np.insert(vx_s.astype(float), _brk, np.nan)
            vy_s = np.insert(vy_s.astype(float), _brk, np.nan)
            cell_ids_s = np.insert(cell_ids_s, _brk, cell_ids_s[_brk])
    # Find split points where cell_id changes
    change = np.flatnonzero(cell_ids_s[1:] != cell_ids_s[:-1]) + 1
    unique_ids = cell_ids_s[np.r_[0, change]]
    vx_groups = np.split(vx_s, change)
    vy_groups = np.split(vy_s, change)
    return {cid: (vxg, vyg) for cid, vxg, vyg in zip(unique_ids, vx_groups, vy_groups)}


def _gdf_to_bounds_dict(gdf) -> dict:
    """Convert GeoDataFrame of cell polygons back to {cell_id: (x_verts, y_verts)}."""
    import shapely
    geoms = np.asarray(gdf.geometry.values)
    # Polygons (type id 3) and MultiPolygons (6: a cell with several rings, e.g. several
    # nuclei); missing/empty geometries are skipped as before
    _tid = shapely.get_type_id(geoms)
    ok = ((_tid == 3) | (_tid == 6)) & ~shapely.is_empty(geoms)
    if not ok.any():
        return {}
    parts, pidx = shapely.get_parts(geoms[ok], return_index=True)
    coords, ridx = shapely.get_coordinates(shapely.get_exterior_ring(parts),
                                           return_index=True)
    cidx = pidx[ridx]                       # geometry (cell) index of every vertex
    # NaN vertex between two parts of the same cell
    _brk = np.flatnonzero((ridx[1:] != ridx[:-1]) & (cidx[1:] == cidx[:-1])) + 1
    cx, cy = coords[:, 0], coords[:, 1]
    if len(_brk):
        cx = np.insert(cx, _brk, np.nan)
        cy = np.insert(cy, _brk, np.nan)
        cidx = np.insert(cidx, _brk, cidx[_brk])
    change = np.flatnonzero(cidx[1:] != cidx[:-1]) + 1
    _starts = np.r_[0, change]
    keys = gdf.index.values[ok][cidx[_starts]]
    xs = np.split(cx, change)
    ys = np.split(cy, change)
    # Stores written before multi-ring support hold a multi-nucleus cell as ONE ring made of
    # its closed rings back to back. Split such a ring where it returns to its start vertex,
    # but only when every resulting piece is itself a closed ring.
    _first = np.repeat(_starts, np.diff(np.r_[_starts, len(cx)]))
    _pos   = np.arange(len(cx))
    _last  = np.r_[change, len(cx)] - 1
    _mid   = (cx == cx[_first]) & (cy == cy[_first]) & (_pos != _first)
    _mid[_last] = False
    for _g in np.unique(np.searchsorted(_starts, np.flatnonzero(_mid), side="right") - 1):
        gx, gy = xs[_g], ys[_g]
        if np.isnan(gx).any():
            continue
        pieces, a, n = [], 0, len(gx)
        while a < n:
            if a == n - 1 and gx[a] == gx[0] and gy[a] == gy[0]:
                break                       # closing vertex shapely added to the merged ring
            hit = np.flatnonzero((gx[a + 1:] == gx[a]) & (gy[a + 1:] == gy[a]))
            if not len(hit) or hit[0] < 2:
                pieces = []
                break
            b = a + 1 + hit[0]
            pieces.append((a, b + 1))
            a = b + 1
        if len(pieces) > 1:
            xs[_g] = np.concatenate([np.r_[gx[a:b], np.nan] for a, b in pieces])[:-1]
            ys[_g] = np.concatenate([np.r_[gy[a:b], np.nan] for a, b in pieces])[:-1]
    return dict(zip(keys, zip(xs, ys)))


def _build_xenium_sdata(data_dir: str) -> None:
    """Read all raw Xenium files and write spatialdata_xenium.zarr next to them (one-time generation)."""
    try:
        import spatialdata
        from spatialdata.models import TableModel, ShapesModel
        import anndata as ad
        import geopandas as gpd
        from shapely.geometry import Polygon
    except ImportError as e:
        raise ImportError(
            f"spatialdata, anndata, geopandas, and shapely are required to generate the zarr store: {e}\n"
            "Install with: pip install spatialdata anndata geopandas shapely"
        )

    print("  Reading raw files for spatialdata_xenium.zarr generation…", flush=True)

    with open(os.path.join(data_dir, "experiment.xenium")) as f:
        metadata = json.load(f)

    cells = pd.read_parquet(os.path.join(data_dir, "cells.parquet"))
    cells = cells.set_index("cell_id")

    # Secondary analysis is optional: use analysis/ when extracted, else read the
    # same CSVs straight from analysis.tar.gz, else go without UMAP / clustering.
    umap_df = None
    cluster_methods = {}
    _umap_rel   = "analysis/umap/gene_expression_2_components/projection.csv"
    cluster_dir = os.path.join(data_dir, "analysis/clustering")
    _analysis_tar = os.path.join(data_dir, "analysis.tar.gz")
    if os.path.isdir(os.path.join(data_dir, "analysis")):
        if os.path.exists(os.path.join(data_dir, _umap_rel)):
            umap_df = pd.read_csv(os.path.join(data_dir, _umap_rel), index_col="Barcode")
        for method in (sorted(os.listdir(cluster_dir)) if os.path.isdir(cluster_dir) else []):
            path = os.path.join(cluster_dir, method, "clusters.csv")
            if os.path.exists(path):
                df_c = pd.read_csv(path, index_col="Barcode")
                cluster_methods[method] = df_c["Cluster"]
    elif os.path.exists(_analysis_tar):
        try:
            import tarfile
            with tarfile.open(_analysis_tar, "r:gz") as _tf:
                for _m in sorted(_tf.getmembers(), key=lambda m: m.name):
                    _name = _m.name.lstrip("./")
                    _parts = _name.split("/")
                    if not _m.isfile():
                        continue
                    if _name == _umap_rel:
                        umap_df = pd.read_csv(_tf.extractfile(_m), index_col="Barcode")
                    elif (len(_parts) == 4 and _parts[:2] == ["analysis", "clustering"]
                          and _parts[3] == "clusters.csv"):
                        df_c = pd.read_csv(_tf.extractfile(_m), index_col="Barcode")
                        cluster_methods[_parts[2]] = df_c["Cluster"]
        except Exception as exc:
            print(f"  Warning: could not read analysis.tar.gz: {exc}", flush=True)
    if umap_df is None or not {"UMAP-1", "UMAP-2"} <= set(umap_df.columns):
        print("  Note: no UMAP projection found — UMAP coordinates will be empty.", flush=True)
        umap_df = None
    if not cluster_methods:
        print("  Note: no clustering results found — no cluster sets available.", flush=True)

    with h5py.File(os.path.join(data_dir, "cell_feature_matrix.h5"), "r") as f:
        barcodes   = [b.decode() for b in f["matrix/barcodes"][:]]
        gene_names = [g.decode() for g in f["matrix/features/name"][:]]
        ftypes     = ([t.decode() for t in f["matrix/features/feature_type"][:]]
                      if "feature_type" in f["matrix/features"] else None)
        shape      = tuple(f["matrix/shape"][:])
        expr = sp.csc_matrix(
            (f["matrix/data"][:], f["matrix/indices"][:], f["matrix/indptr"][:]),
            shape=shape,
        ).T.tocsr()   # → (cells × genes)

    # Keep only real genes: control probes/codewords, unassigned/deprecated codewords
    # and genomic controls are not genes (thousands of them on Xenium Prime 5K).
    if ftypes is not None:
        _keep = np.array([t == "Gene Expression" for t in ftypes], dtype=bool)
    else:
        _ctrl = ("NegControl", "BLANK_", "UnassignedCodeword", "DeprecatedCodeword",
                 "Intergenic_Region", "GenomicControl")
        _keep = np.array([not g.startswith(_ctrl) for g in gene_names], dtype=bool)
    if _keep.any() and not _keep.all():
        print(f"  Dropping {int((~_keep).sum())} non-gene features "
              f"(controls / unassigned codewords); keeping {int(_keep.sum())} genes", flush=True)
        expr = expr[:, np.flatnonzero(_keep)].tocsr()
        gene_names = [g for g, k in zip(gene_names, _keep) if k]

    print("  Building obs DataFrame…", flush=True)
    df = cells.copy()
    if umap_df is not None:
        df["umap_1"] = umap_df["UMAP-1"].reindex(df.index)
        df["umap_2"] = umap_df["UMAP-2"].reindex(df.index)
    else:
        df["umap_1"] = np.nan
        df["umap_2"] = np.nan
    for method, series in cluster_methods.items():
        df[f"clust__{method}"] = series.reindex(df.index).fillna(0).astype(int)

    # Align expression matrix rows to match df.index order
    barcode_idx = {b: i for i, b in enumerate(barcodes)}
    row_order   = np.array([barcode_idx.get(cid, -1) for cid in df.index], dtype=np.int64)
    valid_mask  = row_order >= 0
    n_cells, n_genes = len(df), len(gene_names)

    if valid_mask.all():
        expr_aligned = expr[row_order].tocsr()
    else:
        rows_v = np.where(valid_mask)[0]
        expr_aligned = sp.lil_matrix((n_cells, n_genes), dtype=np.float32)
        expr_aligned[rows_v] = expr[row_order[valid_mask]]
        expr_aligned = expr_aligned.tocsr()

    # Build AnnData
    var_df  = pd.DataFrame({"is_imputed": False}, index=pd.Index(gene_names, name="gene"))
    obs_df  = df.copy()
    obs_df.index = obs_df.index.astype(str)
    adata   = ad.AnnData(X=sp.csr_matrix(expr_aligned, dtype=np.float32), obs=obs_df, var=var_df)
    adata.uns["metadata"]        = metadata
    adata.uns["cluster_methods"] = list(cluster_methods.keys())
    adata.uns["imputed_genes"]   = []
    try:
        adata = TableModel.parse(adata)
    except Exception:
        pass

    # Build boundary GeoDataFrames
    print("  Building cell boundary shapes…", flush=True)
    _empty_bounds = pd.DataFrame(columns=["cell_id", "vertex_x", "vertex_y"])
    cb_path = os.path.join(data_dir, "cell_boundaries.parquet")
    nb_path = os.path.join(data_dir, "nucleus_boundaries.parquet")
    cb_df = pd.read_parquet(cb_path) if os.path.exists(cb_path) else _empty_bounds
    nb_df = pd.read_parquet(nb_path) if os.path.exists(nb_path) else _empty_bounds

    def _bounds_to_gdf(bounds_dict):
        geoms = {}
        try:
            # Vectorised: one shapely call for all polygons (rings need >= 3 vertices)
            import shapely
            # NaN-separated entries (several rings per cell) → one item per ring
            _items = []
            for cid, (vx, vy) in bounds_dict.items():
                vx = np.asarray(vx, dtype=float)
                if np.isnan(vx).any():
                    _cut = np.flatnonzero(np.isnan(vx))
                    _items.extend((cid, rx, ry) for rx, ry in
                                  zip(np.split(vx, _cut), np.split(np.asarray(vy, dtype=float), _cut)))
                else:
                    _items.append((cid, vx, vy))
            # (pieces after the first start with the NaN separator: drop it)
            _items = [(cid, vx[np.isfinite(vx)], np.asarray(vy)[np.isfinite(vx)])
                      for cid, vx, vy in _items]
            _items = [(cid, vx, vy) for cid, vx, vy in _items if len(vx) >= 3]
            _n     = np.array([len(vx) for _, vx, _ in _items])
            _xy    = np.column_stack([np.concatenate([vx for _, vx, _ in _items]),
                                      np.concatenate([vy for _, _, vy in _items])]).astype(float)
            _polys = shapely.polygons(shapely.linearrings(_xy, indices=np.repeat(np.arange(len(_items)), _n)))
            _multi: dict = {}
            for (cid, _, _), g in zip(_items, _polys):
                if str(cid) in geoms:               # further ring of the same cell
                    _multi.setdefault(str(cid), [geoms[str(cid)]]).append(g)
                else:
                    geoms[str(cid)] = g
            for cid, _parts in _multi.items():
                geoms[cid] = shapely.multipolygons(_parts)
        except Exception:
            geoms = {}
            for cid, (vx, vy) in bounds_dict.items():
                try:
                    _ok = np.isfinite(np.asarray(vx, dtype=float))   # first ring only if several
                    _end = len(_ok) if _ok.all() else int(np.argmin(_ok))
                    geoms[str(cid)] = Polygon(zip(vx[:_end], vy[:_end]))
                except Exception:
                    pass
        gdf = gpd.GeoDataFrame(
            geometry=list(geoms.values()),
            index=pd.Index(list(geoms.keys()), name="cell_id"),
        )
        try:
            return ShapesModel.parse(gdf)
        except Exception:
            return gdf

    shapes = {}
    for key, bdf in (("cell_boundaries", cb_df), ("nucleus_boundaries", nb_df)):
        d = _build_boundary_dict(bdf)
        if d:
            shapes[key] = _bounds_to_gdf(d)

    sdata = spatialdata.SpatialData(
        tables={"table": adata},
        shapes=shapes,
    )

    zarr_path = os.path.join(data_dir, "spatialdata_xenium.zarr")
    print(f"  Writing {os.path.basename(zarr_path)} ({n_cells:,} cells, {n_genes} genes)…", flush=True)
    # Write to a temporary store and rename, so an interrupted write is never
    # mistaken for a complete cache on the next start.
    import shutil
    tmp_path = os.path.join(data_dir, "spatialdata_xenium.tmp.zarr")
    shutil.rmtree(tmp_path, ignore_errors=True)
    sdata.write(tmp_path)
    os.replace(tmp_path, zarr_path)
    print("  spatialdata_xenium.zarr generation complete.", flush=True)


_IMPUTED_SUFFIX_RE = re.compile(r" \[(corr\+imp|imp)\]$")


def _plain_imputed_var_names(adata) -> int:
    """Stores written by older versions of functions/impute.py name imputed genes
    'GENE [imp]' / 'GENE [corr+imp]'. The app's convention is the plain gene name plus
    var['is_imputed'] (the suffix is only a dropdown label), so such names are renamed
    in the in-memory table: plain name, is_imputed=True, and the '[corr+imp]' genes
    listed in uns['split_corrected_imputed_genes']. A suffixed name whose plain form
    is already a column is left as it is. Returns the number of renamed genes."""
    names = [str(g) for g in adata.var_names]
    if not any(n.endswith("imp]") for n in names):
        return 0
    taken = {n for n in names if not _IMPUTED_SUFFIX_RE.search(n)}
    new_names, renamed, corr = [], [], []
    for n in names:
        m = _IMPUTED_SUFFIX_RE.search(n)
        base = n[:m.start()] if m else None
        if base and base not in taken:
            taken.add(base)
            renamed.append(base)
            if m.group(1) == "corr+imp":
                corr.append(base)
            n = base
        new_names.append(n)
    if not renamed:
        return 0
    _iname = adata.var.index.name
    adata.var_names = new_names
    adata.var.index.name = _iname
    if "is_imputed" not in adata.var.columns:
        adata.var["is_imputed"] = False
    adata.var["is_imputed"] = adata.var["is_imputed"].fillna(False).astype(bool)
    adata.var.loc[renamed, "is_imputed"] = True
    _strip = lambda g: _IMPUTED_SUFFIX_RE.sub("", str(g))
    _corr_all = list(dict.fromkeys(
        [_strip(g) for g in adata.uns.get("split_corrected_imputed_genes", [])] + corr))
    _raw_all = [g for g in dict.fromkeys(
        [_strip(g) for g in adata.uns.get("imputed_genes", [])]
        + [g for g in renamed if g not in corr]) if g not in _corr_all]
    adata.uns["split_corrected_imputed_genes"] = _corr_all
    adata.uns["imputed_genes"] = _raw_all
    print(f"  Imputed genes: {len(renamed)} var name(s) with an ' [imp]' / ' [corr+imp]' suffix "
          f"(older functions/impute.py output) are read under their plain names", flush=True)
    return len(renamed)


def _load_from_xenium_sdata(zarr_path: str, data_dir: str) -> dict:
    """Load DATA dict from a spatialdata_xenium.zarr store."""
    try:
        import spatialdata
    except ImportError:
        raise ImportError("spatialdata is required: pip install spatialdata")

    print(f"  Loading from spatialdata_xenium.zarr…", flush=True)
    sdata = spatialdata.read_zarr(zarr_path)
    adata = sdata.tables["table"]
    _plain_imputed_var_names(adata)

    gene_names       = list(adata.var_names)
    gene_name_to_idx = {g: i for i, g in enumerate(gene_names)}
    barcodes         = list(adata.obs_names)
    n                = len(adata)

    # obs order == expr row order (guaranteed by _build_xenium_sdata write order)
    df_to_expr = np.arange(n, dtype=np.int64)

    cell_bounds = {}
    nuc_bounds  = {}
    try:
        cell_bounds = _gdf_to_bounds_dict(sdata.shapes["cell_boundaries"])
    except Exception as e:
        print(f"  Warning: could not load cell boundaries from zarr: {e}", flush=True)
    try:
        nuc_bounds = _gdf_to_bounds_dict(sdata.shapes["nucleus_boundaries"])
    except Exception as e:
        print(f"  Warning: could not load nucleus boundaries from zarr: {e}", flush=True)

    obs_df = adata.obs.copy()
    # obs columns added later through the low-level zarr API (SPLIT clusters /
    # UMAP) are not in the table's column-order, so read_zarr does not return them.
    _load_zarr_obs_into_df(zarr_path, obs_df)
    for _nacol in [c for c in obs_df.columns
                   if c == "cluster_split_10" or c == "niche" or str(c).startswith("roi_")]:
        # stored as plain strings with "" for cells without a value (dropped by
        # SPLIT, outside every ROI, outside the subset the niches were computed on)
        _cs = obs_df[_nacol].astype(str)
        if _nacol == "cluster_split_10" or _cs.isin(["", "nan", "<NA>"]).any():
            obs_df[_nacol] = pd.array(
                [v if v not in ("", "nan", "<NA>") else pd.NA for v in _cs], dtype="string")
    cluster_methods = list(adata.uns.get("cluster_methods", []))
    print(f"  Done: {n:,} cells | {len(gene_names)} genes | {len(cluster_methods)} cluster sets", flush=True)

    return {
        "metadata":          dict(adata.uns.get("metadata", {})),
        "df":                obs_df,
        "gene_names":        gene_names,
        "gene_name_to_idx":  gene_name_to_idx,
        "barcodes":          barcodes,
        "expr":              sp.csr_matrix(adata.X),
        "df_to_expr":        df_to_expr,
        "cluster_methods":   cluster_methods,
        "cell_bounds":       cell_bounds,
        "nucleus_bounds":    nuc_bounds,
        "data_dir":          data_dir,
        "sdata_path":        zarr_path,
        "gene_var":          adata.var,
        "split_corrected_expr": (
            sp.csr_matrix(adata.layers["X_corrected"])
            if "X_corrected" in adata.layers else None
        ),
        "split_corrected_imputed_genes": list(adata.uns.get("split_corrected_imputed_genes", [])),
    }


def load_from_sdata_zarr(zarr_path: str) -> dict:
    """Load DATA dict from an exported SpatialData zarr (e.g. from _save_sdata_to_disk).
    Sets data_dir=None as a sentinel meaning no OME-TIFF image data is available."""
    zarr_path = os.path.abspath(zarr_path)
    data = _load_from_xenium_sdata(zarr_path, data_dir=None)
    # Ensure umap columns exist so make_umap_fig doesn't crash
    for col in ("umap_1", "umap_2"):
        if col not in data["df"].columns:
            data["df"][col] = np.nan
    data["sdata_path"] = zarr_path
    return data


# ─── Locate & load data ───────────────────────────────────────────────────────
if os.environ.get("DATA_DIR"):
    _startup_arg = os.environ["DATA_DIR"]
elif len(sys.argv) > 1:
    _startup_arg = sys.argv[1]
else:
    dirs = [d for d in os.listdir(".") if d.startswith("output-") and os.path.isdir(d)]
    if not dirs:
        print("ERROR: No Xenium output directory found. Pass path as argument or set DATA_DIR env var.")
        sys.exit(1)
    _startup_arg = dirs[0]

if _startup_arg.rstrip("/").endswith(".zarr"):
    DATA = load_from_sdata_zarr(_startup_arg)
else:
    DATA = load_xenium_data(_startup_arg)

# Gene expression cache: keyed by (gene, data_dir, use_corrected) → np.ndarray
# Bounded LRU: one n_cells vector per gene adds up on a 5K panel.
from collections import OrderedDict as _OrderedDict
_gene_expr_cache: "_OrderedDict" = _OrderedDict()
_GENE_EXPR_CACHE_MAX = 32


def _gene_cache_put(key, arr):
    """Store arr in _gene_expr_cache, evicting the least recently used entries."""
    _gene_expr_cache[key] = arr
    try:
        _gene_expr_cache.move_to_end(key)
        while len(_gene_expr_cache) > _GENE_EXPR_CACHE_MAX:
            _gene_expr_cache.popitem(last=False)
    except KeyError:   # cleared by another callback thread meanwhile
        pass
    return arr


# UMAP figure cache: (key_tuple, figure)
_umap_fig_cache: dict = {}

# UMAP dataframe cache (dropna copies of DATA["df"]) and viewport centroid arrays
_umap_df_cache: dict = {}
_viewport_arrays: dict = {}


def _refresh_derived_data() -> None:
    """Recompute everything derived from DATA. Called at startup and after a dataset swap."""
    global _sorted_gene_names, _default_gene
    # CSC matrix for fast column (gene) access — O(nnz_col) vs O(nnz_total) for CSR
    if DATA.get("expr") is not None:
        DATA["expr_csc"] = DATA["expr"].tocsc()
    else:
        DATA.pop("expr_csc", None)
    # Sorted gene names and default gene (avoid re-sorting on every callback)
    _sorted_gene_names = sorted(DATA["gene_names"])
    _default_gene = _sorted_gene_names[0] if _sorted_gene_names else None
    _gene_expr_cache.clear()
    _umap_fig_cache.clear()
    _umap_df_cache.clear()
    _viewport_arrays.clear()


def _install_dataset(new_data: dict) -> None:
    """Replace the contents of DATA with new_data (Load Sample) and rebuild derived state."""
    global _dataset_gen
    # From here on, background jobs started for the previous dataset stop publishing
    _dataset_gen += 1
    # Drop keys the new dataset does not carry (subset originals, SPLIT ids, sdata, …)
    # so they cannot leak from the previous dataset through DATA.update().
    for _k in [k for k in DATA if k not in new_data]:
        DATA.pop(_k, None)
    DATA.update(new_data)
    _refresh_derived_data()
    _reset_morph_caches()
    # WebGL viewer: release the previous bundle's tile / polygon caches
    _va = sys.modules.get("xenium_viewer_api")
    if _va is not None:
        _va.reset(DATA.get("data_dir"))
    _vp = globals().get("_viewer_provider")
    if _vp is not None:
        _vp.forget()


_refresh_derived_data()

# ─── Extra datasets for multi-sample display ──────────────────────────────────
# Each entry is like DATA but with an added "x_offset" key (µm shift on x-axis).
EXTRA_DATASETS: list = []


def _sample_separator_xs() -> list:
    """x (µm, plot space) of the dashed line drawn left of each extra sample: midway
    between the right edge of the sample before it and its own left edge. (x_offset moves
    a sample's *minimum* x 500 µm past the previous sample, so x_offset - 250 is in the
    gap only when that minimum is 0.) Used by both renderers."""
    xs = []
    try:
        prev_max = float(DATA["df"]["x_centroid"].max())
    except Exception:
        prev_max = float("nan")
    for eds in EXTRA_DATASETS:
        off = float(eds.get("x_offset", 0.0))
        ex = eds["df"]["x_centroid"]
        lo = float(ex.min()) + off if len(ex) else float("nan")
        hi = float(ex.max()) + off if len(ex) else float("nan")
        xs.append((prev_max + lo) / 2.0 if np.isfinite(prev_max) and np.isfinite(lo)
                  else off - 250.0)
        if np.isfinite(hi):
            prev_max = hi
    return xs


# ─── Data helpers ─────────────────────────────────────────────────────────────
def get_gene_expression(gene: str) -> np.ndarray:
    """log1p expression for *gene*, aligned to DATA['df'] row order.
    Genes with ' [imp]' suffix are served from DATA['expr'] if written back to zarr,
    with fallback to _spage_state['result'] for pre-zarr cached results.
    Results are cached to avoid recomputation on pan/zoom."""
    _cache_key = (gene, DATA.get("data_dir"))
    _hit = _gene_expr_cache.get(_cache_key)
    if _hit is not None:
        try:
            _gene_expr_cache.move_to_end(_cache_key)
        except KeyError:
            pass
        return _hit

    if gene.endswith(" [imp]"):
        base = gene[:-6]
        # Check if imputed gene was written back into DATA["expr"]
        if base in DATA.get("gene_name_to_idx", {}):
            gene_idx = DATA["gene_name_to_idx"][base]
            expr_csc = DATA.get("expr_csc")# or DATA["expr"]
            raw  = expr_csc[:, gene_idx].toarray().ravel()
            idx  = DATA["df_to_expr"]
            vals = np.where(idx >= 0, raw[np.clip(idx, 0, len(raw) - 1)], 0.0)
            result = np.log1p(vals)
            _gene_cache_put(_cache_key, result)
            return result
        # Fallback: old-style _spage_state result DataFrame, or streaming zarr/parquet
        with _spage_lock:
            res       = _spage_state.get("result")
            res_path  = _spage_state.get("result_path")
            res_genes = _spage_state.get("result_genes") or []
        if res is not None and base in res.columns:
            # Result rows follow DATA["df"] as it was when SpaGE ran; realign by
            # cell id when a subset has been applied or cleared since.
            if len(res) != len(DATA["df"]) and res.index.is_unique:
                _ridx = DATA["df"].index
                if res.index.dtype == object and _ridx.dtype != object:
                    _ridx = _ridx.astype(str)
                result = res[base].reindex(_ridx).fillna(0).values.astype(np.float64)
            else:
                result = res[base].values.astype(np.float64)
            # log1p like every other path (write-back column above, _get_expr_values):
            # the same imputed gene must not change scale with the path that serves it
            result = np.log1p(np.clip(result, 0, None))
            _gene_cache_put(_cache_key, result)
            return result
        if res_path and base in res_genes:
            try:
                if os.path.isdir(res_path):   # zarr
                    import zarr as _zarr_ge
                    _z_ge = _zarr_ge.open_array(res_path, mode='r')
                    _gi   = res_genes.index(base)
                    result = np.array(_z_ge[:, _gi], dtype=np.float64)
                else:                          # large parquet — read single column
                    result = pd.read_parquet(res_path, columns=[base])[base].values.astype(np.float64)
                result = _align_expr_rows_to_df(result)
                if len(result) != len(DATA["df"]):
                    # streamed under another subset(): rows cannot be matched to cells
                    raise ValueError(f"result has {len(result):,} rows for "
                                     f"{len(DATA['df']):,} cells — re-run SpaGE")
                result = np.log1p(np.clip(result, 0, None))   # same scale as the other paths
                _gene_cache_put(_cache_key, result)
                return result
            except Exception as _sge:
                print(f"  SpaGE: streaming read failed for {base}: {_sge}", flush=True)
        return np.zeros(len(DATA["df"]), dtype=np.float64)
    gene_idx = DATA["gene_name_to_idx"][gene]
    expr_csc = DATA.get("expr_csc")# or DATA["expr"]
    raw  = expr_csc[:, gene_idx].toarray().ravel()
    idx  = DATA["df_to_expr"]
    vals = np.where(idx >= 0, raw[np.clip(idx, 0, len(raw) - 1)], 0.0)
    result = np.log1p(vals)
    _gene_cache_put(_cache_key, result)
    return result


def _xenium_gene_values(gene, use_corrected: bool = False):
    """Values the Xenium source colours *gene* with (SPLIT-corrected when asked for and
    available, else get_gene_expression), or None when the dataset has no such gene - a
    selection left from another dataset, or no selection. Both renderers then draw
    transcript counts, as they do for a Baysor / Proseg run without the gene."""
    if not gene:
        return None
    vals = _get_expr_values(gene, use_corrected=True) if use_corrected else None
    if vals is None:
        try:
            vals = get_gene_expression(gene)
        except KeyError:
            return None
    return vals


def _panel_gene_names() -> list:
    """Measured panel genes: DATA['gene_names'] without SpaGE-imputed entries."""
    gv = DATA.get("gene_var")
    if gv is not None and "is_imputed" in gv.columns:
        return [g for g in DATA["gene_names"] if not bool(gv.loc[g, "is_imputed"])]
    return list(DATA["gene_names"])


def cluster_col(method: str) -> str:
    return f"clust__{method}"


def cluster_color_map(method: str) -> dict:
    col      = cluster_col(method)
    clusters = sorted(DATA["df"][col].unique())
    return {c: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, c in enumerate(clusters)}


def viewport_cell_ids(relayout: dict) -> list | None:
    """
    Return list of cell_ids whose centroid falls within the current spatial
    viewport, or None if no viewport info is available.
    Coordinates in relayout are in µm (plot space).
    """
    x0 = relayout.get("xaxis.range[0]")
    x1 = relayout.get("xaxis.range[1]")
    y0 = relayout.get("yaxis.range[0]")
    y1 = relayout.get("yaxis.range[1]")

    if None in (x0, x1, y0, y1):
        return None

    # Cache extracted numpy arrays to avoid pandas overhead on every call
    if "xc" not in _viewport_arrays:
        df = DATA["df"]
        _viewport_arrays["xc"] = df["x_centroid"].values
        _viewport_arrays["yc"] = df["y_centroid"].values
        _viewport_arrays["idx"] = df.index.values

    xc = _viewport_arrays["xc"]
    yc = _viewport_arrays["yc"]
    idx = _viewport_arrays["idx"]

    # Plot coords are already in µm (x = x_centroid, y = -y_centroid).
    xc_min, xc_max = float(x0), float(x1)
    yc_min, yc_max = float(-y1), float(-y0)   # un-negate

    mask = (xc >= xc_min) & (xc <= xc_max) & (yc >= yc_min) & (yc <= yc_max)
    return idx[mask].tolist()


def viewport_reseg_cell_ids(relayout: dict, cells_df) -> list | None:
    """Like viewport_cell_ids but uses a reseg cells_df (Baysor/Proseg) instead of DATA['df']."""
    x0 = relayout.get("xaxis.range[0]")
    x1 = relayout.get("xaxis.range[1]")
    y0 = relayout.get("yaxis.range[0]")
    y1 = relayout.get("yaxis.range[1]")
    if None in (x0, x1, y0, y1):
        return None
    xc = cells_df["x_centroid"].values
    yc = cells_df["y_centroid"].values
    idx = cells_df.index.values
    xc_min, xc_max = float(x0), float(x1)
    yc_min, yc_max = float(-y1), float(-y0)
    mask = (xc >= xc_min) & (xc <= xc_max) & (yc >= yc_min) & (yc <= yc_max)
    return [str(i) for i in idx[mask]]


def build_boundary_trace(cell_ids: list, bounds_dict: dict, color: str, name: str) -> go.Scatter | None:
    """Build a single NaN-separated Scatter trace for a set of polygon boundaries."""
    # Collect polygon arrays, compute total size for pre-allocation
    polys = []
    total = 0
    for cid in cell_ids:
        entry = bounds_dict.get(cid)
        if entry is not None:
            polys.append(entry)
            total += len(entry[0]) + 1  # +1 for NaN separator
    if not polys:
        return None
    all_x = np.empty(total, dtype=np.float64)
    all_y = np.empty(total, dtype=np.float64)
    pos = 0
    for vx, vy in polys:
        vx = np.asarray(vx, dtype=np.float64)
        vy = np.asarray(vy, dtype=np.float64)
        n = len(vx)
        all_x[pos:pos + n] = vx
        all_y[pos:pos + n] = -vy
        pos += n
        all_x[pos] = np.nan
        all_y[pos] = np.nan
        pos += 1
    return go.Scatter(
        x=all_x, y=all_y,
        mode="lines",
        line=dict(color=color, width=0.8),
        name=name,
        hoverinfo="skip",
        showlegend=True,
    )


# ─── Figure builders ──────────────────────────────────────────────────────────
def _base_layout(title, xlabel, ylabel, equal_aspect=False):
    layout = dict(
        template="plotly_dark",
        paper_bgcolor=PLOT_BG, plot_bgcolor=PLOT_BG,
        margin=dict(l=50, r=65, t=38, b=48),
        xaxis=dict(title=xlabel, showgrid=False, zeroline=False, color=TEXT),
        yaxis=dict(title=ylabel, showgrid=False, zeroline=False, color=TEXT),
        font=dict(color=TEXT, size=11),
        title=dict(text=title, font=dict(size=13, color=TEXT), x=0.5, xanchor="center"),
        hoverlabel=dict(bgcolor=CARD_BG, font_color=TEXT),
    )
    if equal_aspect:
        layout["yaxis"]["scaleanchor"]  = "x"
        layout["yaxis"]["scaleratio"]   = 1
        layout["yaxis"]["constrain"]    = "domain"   # shrink plot domain, not data range
        layout["xaxis"]["constrain"]    = "domain"   # keep both axes consistent
    return layout


def _categorical_traces(x, y, df, method, size, opacity, mode="spatial"):
    cmap = cluster_color_map(method)
    col  = cluster_col(method)
    traces = []
    for c in sorted(df[col].unique()):
        mask = (df[col] == c).values
        mk   = size if mode == "spatial" else max(2, size * 1.3)
        traces.append(go.Scattergl(
            x=x[mask], y=y[mask],
            mode="markers",
            marker=dict(size=mk, color=cmap[c], opacity=opacity),
            name=f"Cluster {c}",
            legendgroup=f"c{c}",
            showlegend=(mode == "spatial"),
            text=df.index[mask].tolist(),
            customdata=df.index[mask].tolist(),
            hovertemplate="<b>%{text}</b><extra>Cluster " + str(c) + "</extra>",
        ))
    return traces


def _cell_type_color_map(labels_key: str, df) -> dict:
    """Return {cell_type: color} map consistent with _cell_type_traces ordering."""
    with _annot_lock:
        labels = _annot_state.get(labels_key)
    if labels is None:
        return {}
    aligned = labels.reindex(df.index.astype(str)).fillna("Unknown")
    cell_types = sorted(aligned.unique())
    return {ct: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, ct in enumerate(cell_types)}


def _cell_type_traces(x, y, df, size, opacity, mode="spatial", labels_key="labels_celltypist",
                      invisible=False):
    """Categorical traces coloured by cell type annotation.

    When invisible=True, scatter markers are transparent (for hover/click only when pies
    are rendered as layout shapes). Legend entries are added as zero-length traces.
    """
    with _annot_lock:
        labels = _annot_state.get(labels_key)
    if labels is None:
        _ids = df.index.tolist()        # ids as on every other trace: hover and click work
        return [go.Scattergl(x=x, y=y, mode="markers",
                             marker=dict(size=(size if mode == "spatial" else max(2, size * 1.3)),
                                         color=MUTED, opacity=opacity),
                             text=_ids, customdata=_ids,
                             hovertemplate="<b>%{text}</b><extra>No annotation</extra>",
                             name="No annotation", showlegend=(mode == "spatial"))]

    # Align labels to df index — cast both to str to handle int vs str mismatch
    aligned = labels.reindex(df.index.astype(str)).fillna("Unknown")
    cell_types = sorted(aligned.unique())
    cmap = {ct: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, ct in enumerate(cell_types)}

    traces = []
    for ct in cell_types:
        mask = (aligned == ct).values
        mk   = size if mode == "spatial" else max(2, size * 1.3)
        if invisible:
            # Ghost scatter for hover/click; add a visible legend-only trace separately
            traces.append(go.Scattergl(
                x=x[mask], y=y[mask], mode="markers",
                marker=dict(size=mk, color=cmap[ct], opacity=0),
                name=ct, legendgroup=ct, showlegend=False,
                text=df.index[mask].tolist(), customdata=df.index[mask].tolist(),
                hovertemplate="<b>%{text}</b><extra>" + ct + "</extra>",
            ))
            # Zero-length legend entry so the legend still shows cell type → color
            traces.append(go.Scattergl(
                x=[None], y=[None], mode="markers",
                marker=dict(size=mk, color=cmap[ct]),
                name=ct, legendgroup=ct, showlegend=True,
            ))
        else:
            traces.append(go.Scattergl(
                x=x[mask], y=y[mask], mode="markers",
                marker=dict(size=mk, color=cmap[ct], opacity=opacity),
                name=ct, legendgroup=ct,
                showlegend=(mode == "spatial"),
                text=df.index[mask].tolist(), customdata=df.index[mask].tolist(),
                hovertemplate="<b>%{text}</b><extra>" + ct + "</extra>",
            ))
    return traces


def _align_expr_rows_to_df(full):
    """Map a per-expression-row array (one value per row of DATA['expr']) onto
    the current DATA['df'] rows via DATA['df_to_expr']. Arrays of any other
    length are returned unchanged. Identity mapping (no subset) is a no-op."""
    d2e = DATA.get("df_to_expr")
    if d2e is None or DATA.get("expr") is None or len(full) != DATA["expr"].shape[0]:
        return full
    d2e = np.asarray(d2e)
    if len(d2e) == len(full) and (d2e == np.arange(len(full))).all():
        return full
    return np.where(d2e >= 0, full[np.clip(d2e, 0, len(full) - 1)], 0).astype(full.dtype)


def _csc_view(holder: dict, key: str):
    """holder[key] as CSC for O(nnz_col) gene lookups. The CSC copy is built on
    first use and kept in holder[key + '_csc']; it is rebuilt automatically when
    holder[key] is replaced by another matrix object."""
    m = holder.get(key)
    if m is None or not sp.issparse(m) or m.format == "csc":
        return m
    ck = key + "_csc"
    c = holder.get(ck)
    if c is None or holder.get(ck + "_src") is not m:
        c = m.tocsc()
        holder[ck + "_src"] = m
        holder[ck] = c
    return c


def _get_expr_values(gene: str, alt_res=None, use_corrected: bool = False) -> "np.ndarray | None":
    """Unified expression lookup supporting original and SPLIT-corrected counts."""
    lookup = gene.replace(" [imp]", "").replace(" [corr+imp]", "")
    is_imputed_gene = ("[imp]" in gene) or ("[corr+imp]" in gene)
    if alt_res is not None:
        _corr = _csc_view(alt_res, "split_corrected_expr") if use_corrected else None
        expr = _corr if _corr is not None else _csc_view(alt_res, "expr")
        gni  = alt_res.get("gene_name_to_idx") or DATA.get("gene_name_to_idx", {})
    else:
        _corr = _csc_view(DATA, "split_corrected_expr") if use_corrected else None
        expr = _corr if _corr is not None else DATA.get("expr_csc")# or DATA.get("expr")
        gni  = DATA.get("gene_name_to_idx", {})
    if use_corrected and is_imputed_gene:
        # Imputed genes are stored in X only: X_corrected has no values for them (a
        # store reloaded from disk carries all-zero padding columns there, which must
        # not be shown as expression). A gene imputed from corrected counts
        # (functions/impute.py --use_corrected) is read from its X column; any other
        # imputed gene has no corrected values - the caller shows the original ones.
        _corr_imp = (alt_res.get("split_corrected_imputed_genes", []) if alt_res is not None
                     else DATA.get("split_corrected_imputed_genes", [])) or []
        if lookup not in _corr_imp:
            return None
        expr = _csc_view(alt_res, "expr") if alt_res is not None else DATA.get("expr_csc")
    if expr is not None and lookup in gni:
        idx = gni[lookup]
        if idx < expr.shape[1]:
            _col = expr.getcol(idx).toarray().ravel().astype(np.float32)
            if alt_res is None:
                _col = _align_expr_rows_to_df(_col)
            return np.log1p(_col)
    # If corrected mode is active and this is an imputed gene not in the corrected-imputed list,
    # do NOT fall through to the zarr fallback (which holds uncorrected imputed values).
    if use_corrected and is_imputed_gene:
        _corr_imp = (alt_res.get("split_corrected_imputed_genes", []) if alt_res is not None
                     else DATA.get("split_corrected_imputed_genes", []))
        if lookup not in _corr_imp:
            return None
    # Streaming SpaGE fallback — gene in zarr but not in expr index
    # For reseg: prefer per-alt_res zarr (correct row count) over global spage_state
    if alt_res is not None:
        _rp = alt_res.get("spage_result_path")
        _rg = alt_res.get("spage_result_genes") or []
    else:
        _rp, _rg = None, []
    if not (_rp and lookup in _rg):
        # Only fall back to global Xenium SpaGE state when NOT in reseg mode;
        # the global zarr has Xenium cell count rows and would misalign with reseg cells.
        if alt_res is None:
            with _spage_lock:
                _rp = _spage_state.get("result_path")
                _rg = _spage_state.get("result_genes") or []
        else:
            return None
    if _rp and lookup in _rg:
        try:
            if os.path.isdir(_rp):
                import zarr as _zarr_ev
                _gi_ev = _rg.index(lookup)
                _zcol = np.array(
                    _zarr_ev.open_array(_rp, mode='r')[:, _gi_ev], dtype=np.float32)
                if alt_res is None:
                    _zcol = _align_expr_rows_to_df(_zcol)
                    if len(_zcol) != len(DATA["df"]):
                        # streamed under another subset(): rows cannot be matched to cells
                        raise ValueError(f"result has {len(_zcol):,} rows for "
                                         f"{len(DATA['df']):,} cells — re-run SpaGE")
                return np.log1p(_zcol)
        except Exception as _e:
            print(f"  SpaGE zarr read error for {lookup!r}: {_e}", flush=True)
    return None


def _get_reseg_expr_values(gene: str, alt_res: dict) -> "np.ndarray | None":
    """log1p expression for *gene* in resegmented cells, or None if not available.
    Uses alt_res['gene_name_to_idx'] if present (includes reseg-imputed genes),
    falling back to DATA['gene_name_to_idx'] for panel genes."""
    expr = _csc_view(alt_res, "expr")
    if expr is None:
        return None
    # Strip [imp] suffix if present
    lookup = gene[:-6] if gene.endswith(" [imp]") else gene
    gni = alt_res.get("gene_name_to_idx") or DATA["gene_name_to_idx"]
    if lookup not in gni:
        return None
    idx = gni[lookup]
    if idx >= expr.shape[1]:
        return None
    col = expr.getcol(idx)
    vals = col.toarray().ravel().astype(np.float32)
    return np.log1p(vals)


# Figure-specific layout shapes (multi-sample separators + RCTD pies) of the last
# spatial figure, so callbacks that patch layout.shapes can keep them.
_spatial_base_shapes: list = []


def _spatial_overlay_shapes(sdata_roi_on: bool = False, sdata_patches_on: bool = False) -> list:
    """Layout shapes that do not depend on the figure: saved ROI outlines, the
    pending lasso hull and the sopa tissue-ROI / patch-grid overlays."""
    shapes = []
    with _roi_lock:
        roi_visible = _roi_state["show"]
        rois_snap   = list(_roi_state["rois"])
        pending     = _roi_state.get("pending_hull")
    if roi_visible and rois_snap:
        shapes += _roi_shapes_for_fig(rois_snap)
    if pending:
        shapes += _roi_shapes_for_fig([], pending_hull=pending)
    if sdata_roi_on or sdata_patches_on:
        shapes += _sdata_overlays_to_shapes(sdata_roi_on, sdata_patches_on)
    return shapes


def _rctd_pie_shapes_for_view(color_by, relayout):
    """RCTD weight pies for the cells inside the current viewport (single-sample
    Xenium view). Returns None when pies do not apply to *color_by*, and an empty
    list when more than PIE_THRESHOLD cells are in view."""
    if EXTRA_DATASETS or not str(color_by or "").startswith("cell_type:"):
        return None
    _lkey = f"labels_{color_by.split(':')[1]}"
    with _annot_lock:
        _weights_df = _annot_state.get(f"rctd_weights_{_lkey}")
    if _weights_df is None:
        return None
    df = DATA["df"]
    df_vp = df
    if relayout:
        try:
            _x0 = float(relayout.get("xaxis.range[0]", -1e18))
            _x1 = float(relayout.get("xaxis.range[1]",  1e18))
            _y0 = float(relayout.get("yaxis.range[0]", -1e18))
            _y1 = float(relayout.get("yaxis.range[1]",  1e18))
            if _x1 - _x0 < 1e17:  # real range, not default placeholder
                x =  df["x_centroid"].values
                y = -df["y_centroid"].values
                df_vp = df[(x >= _x0) & (x <= _x1) & (y >= _y0) & (y <= _y1)]
        except Exception:
            pass
    if len(df_vp) > PIE_THRESHOLD:
        return []
    # colours from the full frame so pies match the scatter traces
    return _build_rctd_pie_shapes(df_vp, _weights_df, _cell_type_color_map(_lkey, df))


def make_spatial_fig(color_by, method, gene, size, opacity,
                     boundary_toggles, relayout,
                     morph_image=None, extra_title="", baysor_active=False, proseg_active=False,
                     use_corrected: bool = False, cbar_range=None,
                     sdata_roi_on: bool = False, sdata_patches_on: bool = False,
                     density=None):
    # Choose data source: Proseg > Baysor > original Xenium (priority order)
    with _proseg_lock:
        pres = _proseg_state["result"] if proseg_active and _proseg_state["result"] else None
    with _baysor_lock:
        bres = _baysor_state["result"] if baysor_active and not pres and _baysor_state["result"] else None

    alt_res = pres or bres
    # Gene-set score ("geneset:<name>"): one value per cell of the view, or None when
    # the set cannot be scored - transcript counts are drawn then, as for a missing gene
    _gs = None
    if str(color_by or "").startswith("geneset:"):
        _gs = _geneset_color(color_by, "proseg" if pres else "baysor" if bres else "xenium",
                             use_corrected)
        if _gs is None:
            color_by = "transcript_counts"

    def _gs_trace(gx, gy, ids):
        return go.Scattergl(
            x=gx, y=gy, mode="markers",
            marker=_geneset_marker(_gs[0], _gs[1], _gs[2], cbar_range, size=size, opacity=opacity),
            text=ids, customdata=ids,
            hovertemplate="<b>%{text}</b><br>" + _gs[2] + ": %{marker.color:.2f}<extra></extra>",
            name=_gs[2])
    _separator_shapes = []   # populated later for multi-sample mode
    _pie_shapes = []         # RCTD pie chart wedge shapes (single-dataset, Xenium only)

    # Helper: apply log1p for transcript_counts; build colorbar kwargs with optional cmin/cmax
    def _color_vals(raw_vals, color_key):
        v = np.log1p(raw_vals) if color_key == "transcript_counts" else raw_vals.astype(float)
        return v
    def _cbar_kwargs():
        kw = {}
        if cbar_range:
            if cbar_range[0] is not None:
                kw["cmin"] = cbar_range[0]
            if cbar_range[1] is not None:
                kw["cmax"] = cbar_range[1]
        return kw
    if alt_res is not None:
        source_label = " [Proseg]" if pres else " [Baysor]"
        bdf      = alt_res["cells_df"]
        x        =  bdf["x_centroid"].values
        y        = -bdf["y_centroid"].values
        cell_ids     = bdf.index.tolist()
        cell_ids_str = [str(c) for c in cell_ids]
        _ids_arr     = np.asarray(cell_ids_str)
        show_legend  = False
        traces       = None   # filled below

        if color_by == "niche":
            if "niche" in bdf.columns:
                niche_vals = _niche_str(bdf["niche"])
                unique_niches = sorted(niche_vals.unique(), key=lambda v: (0, int(v)) if v.isdigit() else (1, v))
                cmap = {n: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, n in enumerate(unique_niches)}
                traces = []
                for n in unique_niches:
                    mask = (niche_vals == n).values
                    traces.append(go.Scattergl(
                        x=x[mask], y=y[mask], mode="markers",
                        marker=dict(size=size, color=cmap[n], opacity=opacity),
                        name=_niche_name(n), legendgroup=n, showlegend=True,
                        text=_ids_arr[mask], customdata=_ids_arr[mask],
                        hovertemplate="<b>%{text}</b><extra>Niche " + n + "</extra>",
                    ))
                show_legend = True
            # else fall through to transcript_counts

        elif color_by == "cluster":
            # Look for any cluster column in cells_df (added after UMAP/clustering on reseg cells)
            # When corrected counts are active, prefer cluster_split_* columns
            _cluster_cols = _reseg_cluster_cols(bdf.columns)
            if use_corrected:
                cluster_col = next((c for c in _cluster_cols if "split" in c), None) or next(iter(_cluster_cols), None)
            else:
                cluster_col = next((c for c in _cluster_cols if "split" not in c), None) or next(iter(_cluster_cols), None)
            if cluster_col is not None:
                cluster_vals = bdf[cluster_col].astype(str)
                unique_clusters = sorted(cluster_vals.unique(), key=lambda v: (0, int(v)) if v.isdigit() else (1, v))
                cmap = {cl: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, cl in enumerate(unique_clusters)}
                traces = []
                for cl in unique_clusters:
                    mask = (cluster_vals == cl).values
                    traces.append(go.Scattergl(
                        x=x[mask], y=y[mask], mode="markers",
                        marker=dict(size=size, color=cmap[cl], opacity=opacity),
                        name=f"Cluster {cl}", legendgroup=cl, showlegend=True,
                        text=_ids_arr[mask], customdata=_ids_arr[mask],
                        hovertemplate="<b>%{text}</b><extra>Cluster " + cl + "</extra>",
                    ))
                show_legend = True
            # If no cluster column: fall through to generic fallback (transcript_counts)

        elif color_by.startswith("cell_type:"):
            _method = color_by.split(":")[1]
            aligned = _reseg_cell_type_labels(_method, alt_res, cell_ids_str)
            if aligned is None:     # no labels, or stale ones (cleared by the helper)
                color_by = "transcript_counts"
            else:
                cell_types = sorted(aligned.unique())
                cmap = {ct: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, ct in enumerate(cell_types)}
                traces = []
                for ct in cell_types:
                    mask = (aligned == ct).values
                    traces.append(go.Scattergl(
                        x=x[mask], y=y[mask], mode="markers",
                        marker=dict(size=size, color=cmap[ct], opacity=opacity),
                        name=ct, legendgroup=ct, showlegend=True,
                        text=_ids_arr[mask], customdata=_ids_arr[mask],
                        hovertemplate="<b>%{text}</b><extra>" + ct + "</extra>",
                    ))
                show_legend = True

        elif _gs is not None:
            if len(_gs[0]) == len(bdf):
                traces = [_gs_trace(x, y, cell_ids_str)]

        elif color_by == "gene":
            vals = _get_expr_values(gene, alt_res, use_corrected=use_corrected)
            if vals is None and use_corrected:
                # imputed gene: no corrected values exist, show the original ones
                # (as the Xenium path does)
                vals = _get_expr_values(gene, alt_res, use_corrected=False)
            if vals is not None:
                traces = [go.Scattergl(
                    x=x, y=y, mode="markers",
                    marker=dict(size=size, color=vals, colorscale="Plasma", opacity=opacity,
                                showscale=True,
                                colorbar=dict(title=f"{gene}<br>(log1p)", thickness=12, len=0.5, x=1.02),
                                **_cbar_kwargs()),
                    text=cell_ids_str, customdata=cell_ids_str,
                    hovertemplate="<b>%{text}</b><br>" + gene + ": %{marker.color:.2f}<extra></extra>",
                    name=gene,
                )]

        elif color_by and color_by.startswith("roi_") and color_by in bdf.columns:
            labels = bdf[color_by].fillna("(none)").astype(str)
            u_vals = [v for v in sorted(labels.unique()) if v != "(none)"]
            cmap   = {v: _roi_color(i) for i, v in enumerate(u_vals)}
            cmap["(none)"] = "#666666"
            colors = labels.map(cmap).values
            traces = [go.Scattergl(
                x=x, y=y, mode="markers",
                marker=dict(size=size, color=colors, opacity=opacity),
                text=cell_ids_str, customdata=cell_ids_str,
                hovertemplate="<b>%{text}</b><br>" + color_by + ": %{text}<extra></extra>",
                name=color_by,
            )]
            show_legend = False

        if traces is None:
            # Fallback: QC column if available, otherwise transcript counts
            if color_by in bdf.columns:
                vals  = _color_vals(bdf[color_by].values, color_by)
                label = QC_METRICS.get(color_by, color_by)
                if color_by == "transcript_counts":
                    label = "Transcript Counts (log1p)"
                cs    = COLORSCALES.get(color_by, "Viridis")
            else:
                vals  = np.log1p(bdf["transcript_counts"].values)
                label = "Transcript Counts (log1p)"
                cs    = "Viridis"
            traces = [go.Scattergl(
                x=x, y=y, mode="markers",
                marker=dict(size=size, color=vals, colorscale=cs, opacity=opacity, showscale=True,
                            colorbar=dict(title=label, thickness=12, len=0.5, x=1.02),
                            **_cbar_kwargs()),
                text=cell_ids_str, customdata=cell_ids_str,
                hovertemplate="<b>Cell %{text}</b><br>" + label + ": %{marker.color:.2f}<extra></extra>",
                name=label,
            )]
    else:
        df  = DATA["df"]
        x   =  df["x_centroid"].values   # x_centroid is in µm
        y   = -df["y_centroid"].values   # y_centroid is in µm, negate for plot
        source_label    = ""

        # ── Multi-sample: merge extra datasets ──────────────────────────
        if EXTRA_DATASETS:
            # Concatenate extra datasets into combined arrays
            all_x       = [x]
            all_y       = [y]
            all_ids     = [df.index.tolist()]
            all_dfs     = [df]
            all_offsets = [0.0]
            for eds in EXTRA_DATASETS:
                edf    = eds["df"]
                offset = eds["x_offset"]
                all_x.append(edf["x_centroid"].values + offset)
                all_y.append(-edf["y_centroid"].values)
                all_ids.append(edf.index.tolist())
                all_dfs.append(edf)
                all_offsets.append(offset)

            x_combined   = np.concatenate(all_x)
            y_combined   = np.concatenate(all_y)
            ids_combined = [cid for chunk in all_ids for cid in chunk]

            # Build per-sample separator annotations (vertical dashed lines)
            _separator_shapes = []
            for sep_x in _sample_separator_xs():     # middle of each gap
                _separator_shapes.append(dict(
                    type="line", x0=sep_x, x1=sep_x,
                    y0=0, y1=1, yref="paper",
                    line=dict(color=MUTED, width=1, dash="dot"),
                ))

            # Build color values across all datasets
            if color_by == "cluster":
                # Combine cluster IDs per dataset — use dataset index as prefix to avoid collisions
                all_clust_vals  = []
                all_clust_names = []
                cmap_combined   = {}
                color_idx       = 0
                for di, (edf, offset) in enumerate(zip(all_dfs, all_offsets)):
                    _method = method or (edf.get("cluster_methods", [None])[0]
                                         if hasattr(edf, "get") else None)
                    # edf is a plain DataFrame; cluster_methods come from DATA or EXTRA_DATASETS[di-1]
                    ds = DATA if di == 0 else EXTRA_DATASETS[di - 1]
                    _method = method if method in ds.get("cluster_methods", []) else (ds.get("cluster_methods") or [method])[0]
                    col_name = f"clust__{_method}"
                    if col_name in edf.columns:
                        raw_vals = edf[col_name].values
                        # Prefix dataset index so cluster IDs don't collide across samples
                        prefixed = [f"S{di}:C{v}" for v in raw_vals]
                        all_clust_vals.extend(prefixed)
                        for pv in prefixed:
                            if pv not in cmap_combined:
                                cmap_combined[pv] = CLUSTER_COLORS[color_idx % len(CLUSTER_COLORS)]
                                color_idx += 1
                        all_clust_names.extend(prefixed)
                    else:
                        # a sample without cluster sets (or without this one): one
                        # placeholder group, coloured like any other label
                        placeholders = [f"S{di}:C0"] * len(edf)
                        all_clust_vals.extend(placeholders)
                        all_clust_names.extend(placeholders)
                        if placeholders and placeholders[0] not in cmap_combined:
                            cmap_combined[placeholders[0]] = CLUSTER_COLORS[color_idx % len(CLUSTER_COLORS)]
                            color_idx += 1

                # Build one trace per unique cluster-label across all samples
                unique_labels = list(dict.fromkeys(all_clust_vals))
                arr_x   = x_combined
                arr_y   = y_combined
                arr_ids = np.array(ids_combined)
                arr_lbl = np.array(all_clust_vals)
                traces  = []
                for lbl in unique_labels:
                    mask = arr_lbl == lbl
                    traces.append(go.Scattergl(
                        x=arr_x[mask], y=arr_y[mask], mode="markers",
                        marker=dict(size=size, color=cmap_combined[lbl], opacity=opacity),
                        name=lbl, legendgroup=lbl, showlegend=True,
                        text=arr_ids[mask].tolist(),
                        customdata=arr_ids[mask].tolist(),
                        hovertemplate="<b>%{text}</b><extra>" + lbl + "</extra>",
                    ))
                show_legend = True

            elif color_by == "niche":
                # Combine niche labels across datasets
                all_niche_vals = []
                for edf in all_dfs:
                    if "niche" in edf.columns:
                        all_niche_vals.extend(_niche_str(edf["niche"]).tolist())
                    else:
                        all_niche_vals.extend(["N/A"] * len(edf))
                arr_niche = np.array(all_niche_vals)
                arr_x   = x_combined
                arr_y   = y_combined
                arr_ids = np.array(ids_combined)
                unique_niches = sorted(set(all_niche_vals), key=lambda v: (0, int(v)) if v.isdigit() else (1, v))
                ncmap = {n: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, n in enumerate(unique_niches)}
                traces = []
                for _n in unique_niches:
                    mask = arr_niche == _n
                    traces.append(go.Scattergl(
                        x=arr_x[mask], y=arr_y[mask], mode="markers",
                        marker=dict(size=size, color=ncmap[_n], opacity=opacity),
                        name=_niche_name(_n), legendgroup=_n, showlegend=True,
                        text=arr_ids[mask].tolist(),
                        customdata=arr_ids[mask].tolist(),
                        hovertemplate="<b>%{text}</b><extra>Niche " + _n + "</extra>",
                    ))
                show_legend = True

            elif color_by.startswith("cell_type:"):
                # Combine cell type labels from each dataset's annotation state
                _method = color_by.split(":")[1]
                all_labels_list = []
                with _annot_lock:
                    primary_labels = _annot_state.get(f"labels_{_method}")
                for di, edf in enumerate(all_dfs):
                    if di == 0:
                        lbl_series = primary_labels
                    else:
                        lbl_series = EXTRA_DATASETS[di - 1].get("_cell_type_labels")
                    if lbl_series is not None:
                        aligned = lbl_series.reindex(edf.index).fillna("Unknown")
                        all_labels_list.extend(aligned.tolist())
                    else:
                        all_labels_list.extend(["Unknown"] * len(edf))

                arr_lbl  = np.array(all_labels_list)
                arr_x    = x_combined
                arr_y    = y_combined
                arr_ids  = np.array(ids_combined)
                cell_types = sorted(set(all_labels_list))
                cmap = {ct: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, ct in enumerate(cell_types)}
                traces = []
                for ct in cell_types:
                    mask = arr_lbl == ct
                    traces.append(go.Scattergl(
                        x=arr_x[mask], y=arr_y[mask], mode="markers",
                        marker=dict(size=size, color=cmap[ct], opacity=opacity),
                        name=ct, legendgroup=ct, showlegend=True,
                        text=arr_ids[mask].tolist(),
                        customdata=arr_ids[mask].tolist(),
                        hovertemplate="<b>%{text}</b><extra>" + ct + "</extra>",
                    ))
                show_legend = True

            elif _gs is not None and len(_gs[0]) == len(x_combined):
                traces = [_gs_trace(x_combined, y_combined, ids_combined)]
                show_legend = False

            elif color_by == "gene":
                # Collect expression per dataset
                all_vals = []
                for di, edf in enumerate(all_dfs):
                    if di == 0:
                        _v0 = _xenium_gene_values(gene)     # None: not in this sample
                        all_vals.append(_v0 if _v0 is not None and len(_v0) == len(edf)
                                        else np.zeros(len(edf)))
                    else:
                        eds = EXTRA_DATASETS[di - 1]
                        g_idx = eds.get("gene_name_to_idx", {}).get(gene)
                        if g_idx is not None:
                            raw  = _csc_view(eds, "expr")[:, g_idx].toarray().flatten()
                            idx_ = eds["df_to_expr"]
                            vals_i = np.where(idx_ >= 0, raw[np.clip(idx_, 0, len(raw) - 1)], 0.0)
                            all_vals.append(np.log1p(vals_i))
                        else:
                            all_vals.append(np.zeros(len(edf)))
                vals_combined = np.concatenate(all_vals)
                traces = [go.Scattergl(
                    x=x_combined, y=y_combined, mode="markers",
                    marker=dict(size=size, color=vals_combined, colorscale="Plasma", opacity=opacity,
                                showscale=True,
                                colorbar=dict(title=f"{gene}<br>(log1p)", thickness=12, len=0.5, x=1.02),
                                **_cbar_kwargs()),
                    text=ids_combined, customdata=ids_combined,
                    hovertemplate="<b>%{text}</b><br>" + gene + ": %{marker.color:.2f}<extra></extra>",
                    name=gene,
                )]
                show_legend = False

            elif color_by.startswith("roi_"):
                # ROI class: categorical colours; samples without the column show "(none)"
                labels = pd.concat([
                    (edf[color_by] if color_by in edf.columns
                     else pd.Series(pd.NA, index=edf.index, dtype=object))
                    for edf in all_dfs
                ]).fillna("(none)").astype(str)
                u_vals = [v for v in sorted(labels.unique()) if v != "(none)"]
                cmap   = {v: _roi_color(i) for i, v in enumerate(u_vals)}
                cmap["(none)"] = "#666666"
                traces = [go.Scattergl(
                    x=x_combined, y=y_combined, mode="markers",
                    marker=dict(size=size, color=labels.map(cmap).values, opacity=opacity),
                    text=ids_combined, customdata=ids_combined,
                    hovertemplate="<b>%{text}</b><extra></extra>",
                    name=color_by,
                )]
                show_legend = False

            else:
                # QC / numeric column
                label = QC_METRICS.get(color_by, color_by)
                cs    = COLORSCALES.get(color_by, "Viridis")
                all_vals = []
                for edf in all_dfs:
                    if color_by in edf.columns:
                        all_vals.append(_color_vals(edf[color_by].values, color_by))
                    else:
                        all_vals.append(np.zeros(len(edf)))
                if color_by == "transcript_counts":
                    label = "Transcript Counts (log1p)"
                vals_combined = np.concatenate(all_vals)
                traces = [go.Scattergl(
                    x=x_combined, y=y_combined, mode="markers",
                    marker=dict(size=size, color=vals_combined, colorscale=cs, opacity=opacity,
                                showscale=True,
                                colorbar=dict(title=label, thickness=12, len=0.5, x=1.02),
                                **_cbar_kwargs()),
                    text=ids_combined, customdata=ids_combined,
                    hovertemplate="<b>%{text}</b><br>" + label + ": %{marker.color:.2f}<extra></extra>",
                    name=label,
                )]
                show_legend = False

            source_label = f" [{len(EXTRA_DATASETS) + 1} samples]"

        else:
            # ── Single sample (no extra datasets) ───────────────────────
            # _separator_shapes already = [] from function-level init

            # ── Cell scatter traces ──────────────────────────────────────────
            # A niche / ROI column can be missing (niches computed on a reseg run or a
            # subset, ROI deleted, dataset switched): fall back like the reseg branch.
            # The same goes for any plain column colour (a QC column absent from an
            # exported store) and for 'cluster' when its column does not exist (no cluster
            # sets, or a reseg source is selected but its result is not loaded).
            if _gs is not None and len(_gs[0]) != len(df):
                _gs, color_by = None, "transcript_counts"
            if (color_by not in ("cluster", "gene") and not color_by.startswith("cell_type:")
                    and _gs is None and color_by not in df.columns):
                color_by = "transcript_counts"
            # (`cluster_col` is a local name in this function: spell the column out)
            if color_by == "cluster" and f"clust__{method}" not in df.columns:
                color_by = "transcript_counts"
            # ... and for a gene this dataset does not have (as a reseg run without it)
            _gene_vals = None
            if color_by == "gene":
                _gene_vals = _xenium_gene_values(gene, use_corrected)
                if _gene_vals is None or len(_gene_vals) != len(df):
                    color_by = "transcript_counts"
            if color_by == "niche":
                if "niche" in df.columns:
                    _niche_vals = _niche_str(df["niche"])
                    _unique_niches = sorted(_niche_vals.unique(), key=lambda v: (0, int(v)) if v.isdigit() else (1, v))
                    _ncmap = {n: CLUSTER_COLORS[i % len(CLUSTER_COLORS)] for i, n in enumerate(_unique_niches)}
                    traces = []
                    for _n in _unique_niches:
                        _nmask = (_niche_vals == _n).values
                        _nids = df.index.tolist()
                        traces.append(go.Scattergl(
                            x=x[_nmask], y=y[_nmask], mode="markers",
                            marker=dict(size=size, color=_ncmap[_n], opacity=opacity),
                            name=_niche_name(_n), legendgroup=_n, showlegend=True,
                            text=np.array(_nids)[_nmask].tolist(),
                            customdata=np.array(_nids)[_nmask].tolist(),
                            hovertemplate="<b>%{text}</b><extra>Niche " + _n + "</extra>",
                        ))
                    show_legend = True
                # else fall through — no niche column yet
            elif color_by == "cluster":
                traces, show_legend = _categorical_traces(x, y, df, method, size, opacity), True
            elif color_by.startswith("cell_type:"):
                _method = color_by.split(":")[1]
                _lkey = f"labels_{_method}"
                # Always draw every cell; RCTD weight pies (SVG wedge shapes) are added
                # on top for the cells in view and refreshed on pan/zoom by update_plots.
                traces = _cell_type_traces(x, y, df, size, opacity, "spatial",
                                           labels_key=_lkey)
                _pie_shapes = _rctd_pie_shapes_for_view(color_by, relayout) or []
                show_legend = True
            elif _gs is not None:
                traces, show_legend = [_gs_trace(x, y, df.index.tolist())], False
            elif color_by == "gene":
                vals = _gene_vals
                traces = [go.Scattergl(
                    x=x, y=y, mode="markers",
                    marker=dict(size=size, color=vals, colorscale="Plasma", opacity=opacity,
                                showscale=True,
                                colorbar=dict(title=f"{gene}<br>(log1p)", thickness=12, len=0.5, x=1.02),
                                **_cbar_kwargs()),
                    text=df.index.tolist(), customdata=df.index.tolist(),
                    hovertemplate="<b>%{text}</b><br>" + gene + ": %{marker.color:.2f}<extra></extra>",
                    name=gene,
                )]
                show_legend = False
            elif color_by and color_by.startswith("roi_") and color_by in df.columns:
                labels = df[color_by].fillna("(none)").astype(str)
                u_vals = [v for v in sorted(labels.unique()) if v != "(none)"]
                cmap   = {v: _roi_color(i) for i, v in enumerate(u_vals)}
                cmap["(none)"] = "#666666"
                colors = labels.map(cmap).values
                ids    = df.index.tolist()
                traces = [go.Scattergl(
                    x=x, y=y, mode="markers",
                    marker=dict(size=size, color=colors, opacity=opacity),
                    text=ids, customdata=ids,
                    hovertemplate="<b>%{text}</b><extra></extra>",
                    name=color_by,
                )]
                show_legend = False
            else:
                label = QC_METRICS.get(color_by, color_by)
                vals = (_color_vals(df[color_by].values, color_by) if color_by in df.columns
                        else np.zeros(len(df)))
                if color_by == "transcript_counts":
                    label = "Transcript Counts (log1p)"
                traces = [go.Scattergl(
                    x=x, y=y, mode="markers",
                    marker=dict(size=size, color=vals,
                                colorscale=COLORSCALES.get(color_by, "Viridis"),
                                opacity=opacity, showscale=True,
                                colorbar=dict(title=label, thickness=12, len=0.5, x=1.02),
                                **_cbar_kwargs()),
                    text=df.index.tolist(), customdata=df.index.tolist(),
                    hovertemplate="<b>%{text}</b><br>" + label + ": %{marker.color:.2f}<extra></extra>",
                    name=label,
                )]
                show_legend = False

    # ── Boundary overlay traces ──────────────────────────────────────────
    boundary_toggles = boundary_toggles or []
    boundary_status = ""

    # Each boundary source is rendered independently
    _needs_zoom_msg = False

    def _add_boundary(bounds_dict, color, name, reseg_cells_df=None):
        """Render a boundary set using viewport filtering. reseg_cells_df uses Baysor/Proseg cells."""
        nonlocal _needs_zoom_msg, show_legend
        if not bounds_dict:
            return
        if reseg_cells_df is not None:
            visible = viewport_reseg_cell_ids(relayout or {}, reseg_cells_df)
        else:
            visible = viewport_cell_ids(relayout or {})
        if visible is None:
            _needs_zoom_msg = True
            return
        if len(visible) > BOUNDARY_CELL_LIMIT:
            return
        t = build_boundary_trace(visible, bounds_dict, color, name)
        if t:
            traces.append(t)
            show_legend = True

    # "Xenium Cell/Nuclei Boundaries" always show original Xenium boundaries (zoom required).
    if "cell" in boundary_toggles:
        _add_boundary(DATA["cell_bounds"], "#00d4ff", "Xenium Cell Boundaries")
    if "nucleus" in boundary_toggles:
        _add_boundary(DATA.get("nucleus_bounds", {}), "#ff9f43", "Xenium Nuclei Boundaries")

    # Proseg boundaries (zoom required, uses Proseg cell centroids for viewport)
    if "proseg" in boundary_toggles:
        with _proseg_lock:
            _pres_local = _proseg_state.get("result")
        if _pres_local:
            _add_boundary(_pres_local["cell_bounds"], "#2ed573", "Proseg Boundaries",
                          reseg_cells_df=_pres_local["cells_df"])

    # Baysor boundaries (zoom required, uses Baysor cell centroids for viewport)
    if "baysor" in boundary_toggles:
        with _baysor_lock:
            _bres_local = _baysor_state.get("result")
        if _bres_local:
            _add_boundary(_bres_local["cell_bounds"], "#a29bfe", "Baysor Boundaries",
                          reseg_cells_df=_bres_local["cells_df"])

    if _needs_zoom_msg:
        boundary_status = " · zoom in to see Xenium boundaries"

    title_text = "Spatial View" + source_label + boundary_status + extra_title

    # Transcript density: an SVG heat layer, which plotly.js draws below the WebGL markers
    _dens = _density_heatmap_trace(density, relayout) if density else None
    if _dens is not None:
        if any(getattr(getattr(t, "marker", None), "showscale", False) for t in traces):
            _dens.colorbar.x = 1.12          # beside the cells' own colour bar
        traces = [_dens] + list(traces)
    fig = go.Figure(data=traces)
    if morph_image:
        fig.update_layout(images=[morph_image])
    layout_kwargs = dict(
        **_base_layout(title_text, "X (µm)", "Y (µm)", equal_aspect=True),
        showlegend=show_legend,
        legend=dict(
            bgcolor="rgba(0,0,0,0.45)", font=dict(size=10),
            itemsizing="constant", tracegroupgap=1,
            x=0.01, y=0.99, xanchor="left", yanchor="top",
        ),
        # per dataset: after Load Sample the client must drop the previous zoom
        uirevision=f"spatial-{_dataset_gen}",
    )
    all_shapes = list(_separator_shapes) + list(_pie_shapes)
    _spatial_base_shapes[:] = all_shapes
    all_shapes += _spatial_overlay_shapes(sdata_roi_on, sdata_patches_on)
    if all_shapes:
        layout_kwargs["shapes"] = all_shapes
    fig.update_layout(**layout_kwargs)
    # Explicitly preserve viewport ranges to prevent zoom resets on figure rebuild
    if relayout:
        rx0 = relayout.get("xaxis.range[0]")
        rx1 = relayout.get("xaxis.range[1]")
        ry0 = relayout.get("yaxis.range[0]")
        ry1 = relayout.get("yaxis.range[1]")
        if all(v is not None for v in (rx0, rx1, ry0, ry1)):
            fig.update_layout(
                xaxis_range=[float(rx0), float(rx1)],
                yaxis_range=[float(ry0), float(ry1)],
            )
    return fig


def make_cell_type_abundance_fig(width=None, height=None):
    """Build bar chart of cell type abundances for all computed annotation methods."""
    from plotly.subplots import make_subplots
    import plotly.graph_objects as go

    with _annot_lock:
        label_keys = [k for k in _annot_state if k.startswith("labels_") and _annot_state[k] is not None]
        # Skip generic keys (e.g. "labels_rctd") when a mode-specific key exists
        # (e.g. "labels_rctd_doublet") — they hold the same data and would show as duplicates.
        generic_with_specific = set()
        for key in label_keys:
            suffix = key[len("labels_"):]
            parts = suffix.split("_")
            if len(parts) >= 2 and parts[1] in ("full", "doublet", "multi"):
                generic_with_specific.add(f"labels_{parts[0]}")
        label_keys = [k for k in label_keys if k not in generic_with_specific]

        method_data = []
        for key in label_keys:
            val = _annot_state[key]
            suffix = key[len("labels_"):]
            parts = suffix.split("_", 1)
            base = parts[0].lower()
            if base in ("baysor", "proseg"):
                display = suffix.replace("_", " ").title()
            elif base in ("celltypist", "seurat", "rctd"):
                method_map = {"celltypist": "CellTypist", "seurat": "Seurat", "rctd": "RCTD"}
                method_name = method_map.get(base, base.title())
                if len(parts) > 1:
                    display = f"{method_name} ({parts[1].replace('_', ':')})"
                else:
                    display = method_name
            else:
                display = suffix.replace("_", " ").title()
            method_data.append((display, val))

    if not method_data:
        fig = go.Figure()
        fig.update_layout(
            paper_bgcolor=CARD_BG,
            plot_bgcolor=PLOT_BG,
            font=dict(color=TEXT, size=12),
            margin=dict(l=10, r=10, t=10, b=10),
            annotations=[dict(
                text="No annotation computed yet",
                xref="paper", yref="paper",
                x=0.5, y=0.5, showarrow=False,
                font=dict(size=14, color=TEXT),
            )],
        )
        return fig

    n = len(method_data)
    colors = CLUSTER_COLORS if CLUSTER_COLORS else ["#5B9BD5"]
    fig = make_subplots(
        rows=n, cols=1,
        subplot_titles=[m[0] for m in method_data],
        shared_xaxes=False,
        vertical_spacing=max(0.08, 0.15 / max(n, 1)),
    )

    for i, (name, labels) in enumerate(method_data):
        if hasattr(labels, "value_counts"):
            counts = labels.value_counts(normalize=True).sort_values(ascending=False)
        else:
            import pandas as _pd
            counts = _pd.Series(labels).value_counts(normalize=True).sort_values(ascending=False)
        cell_types = [str(c) for c in counts.index]
        freqs = counts.values
        color = colors[i % len(colors)]
        fig.add_trace(
            go.Bar(
                x=cell_types,
                y=freqs,
                name=name,
                marker_color=color,
                text=[f"{v:.1%}" for v in freqs],
                textposition="outside",
                showlegend=False,
            ),
            row=i + 1, col=1,
        )
        fig.update_yaxes(tickformat=".0%", row=i + 1, col=1,
                         gridcolor=BORDER, zeroline=False)
        fig.update_xaxes(tickangle=-45, row=i + 1, col=1)

    fig.update_layout(
        paper_bgcolor=CARD_BG,
        plot_bgcolor=PLOT_BG,
        font=dict(color=TEXT, size=11),
        margin=dict(l=50, r=20, t=40, b=60),
        showlegend=False,
    )
    for ann in fig.layout.annotations:
        ann.font.color = TEXT
        ann.font.size = 12

    return fig


def _make_placeholder_fig(msg="No analysis computed yet."):
    fig = go.Figure()
    fig.add_annotation(text=msg, xref="paper", yref="paper", x=0.5, y=0.5,
                       showarrow=False, font=dict(color=MUTED, size=13))
    fig.update_layout(paper_bgcolor=CARD_BG, plot_bgcolor=PLOT_BG,
                      margin=dict(l=10, r=10, t=10, b=10),
                      xaxis=dict(visible=False), yaxis=dict(visible=False))
    return fig


